//! ADR-016 parity: the Rust m1 port (sheaf_cell::m1 + sheaf_cohom::m1, through the sheaf-cli m1 adapter) against the
//! Python reference (`python/sheafcore.py` = the gated m1 core), on outputs regenerated by python/m1/make_rust_parity.py.
//!
//! Tolerances (stated; SPEC v1.18 bounds in brackets, ours are tighter where the arithmetic is the same):
//!   δ⁰          : same stored pattern size, |δ_rs − δ_py|max ≤ 1e-12                        [ATOL 1e-9]
//!   L₀          : |L_rs − L_py|max ≤ 1e-12 · max(1, max|L_py|)                              [1e-9 · max(1, max|L|)]
//!   discord     : |d_rs − d_py| ≤ 1e-9 · |d_py| + 1e-12 per edge                            [rel 1e-9 / abs 1e-12]
//!   energy      : |E_rs − E_py| ≤ 1e-9 · Σdiscord + 1e-12 · ‖L‖∞ ‖x‖²                       [R-LAP energy identity]
//!   H⁰ dims     : exact, both routes (SVD: H0Policy::m1_svd(1e-9); eigen: H0Policy::m1_eig(1e-10))
//!   H⁰ basis    : projector |GGᵀ_rs − GGᵀ_py|max ≤ 1e-8; ‖GᵀG − I‖max ≤ 1e-8; ‖δG‖_F ≤ 1e-6 · max(1, σ_max)
//!                 (bases are compared as subspaces: singular vectors are unique only up to rotation)
use serde_json::Value;
use sheaf_cell::m1 as cell;
use sheaf_cell::num::sparse::Csr;
use sheaf_cell::num::tol::{H0Policy, EIG_TOL, M1_RANK_TOL};
use sheaf_cohom::m1 as co;
use sheaf_contract::SheafSpec;

fn fixture() -> Value {
    let p = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/m1/rust_parity.json");
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}
fn f64s(v: &Value) -> Vec<f64> { v.as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect() }
fn mat(v: &Value) -> Vec<Vec<f64>> { v.as_array().unwrap().iter().map(f64s).collect() }
fn dense(a: &Csr) -> Vec<Vec<f64>> {
    let mut d = vec![vec![0.0; a.ncols]; a.nrows];
    for i in 0..a.nrows { for p in a.ptr[i]..a.ptr[i + 1] { d[i][a.idx[p]] += a.val[p]; } } d
}
fn maxdiff(a: &[Vec<f64>], b: &[Vec<f64>]) -> f64 {
    assert_eq!(a.len(), b.len()); a.iter().zip(b).map(|(r, s)| { assert_eq!(r.len(), s.len()); r.iter().zip(s).map(|(x, y)| (x - y).abs()).fold(0.0, f64::max) }).fold(0.0, f64::max)
}
fn amax(a: &[Vec<f64>]) -> f64 { a.iter().flatten().fold(0.0f64, |m, x| m.max(x.abs())) }
fn check_discord(name: &str, got: &[f64], want: &[f64]) -> f64 {
    assert_eq!(got.len(), want.len(), "{name}"); let mut worst = 0.0f64;
    for (j, (g, w)) in got.iter().zip(want).enumerate() {
        let tol = 1e-9 * w.abs() + 1e-12; assert!((g - w).abs() <= tol, "{name} discord[{j}]: {g} vs {w}"); worst = worst.max((g - w).abs() / w.abs().max(1e-300));
    }
    worst
}
fn energy_tol(discord: &[f64], l: &Csr, x: &[f64]) -> f64 {
    let linf = (0..l.nrows).map(|i| (l.ptr[i]..l.ptr[i + 1]).map(|p| l.val[p].abs()).sum::<f64>()).fold(0.0, f64::max);
    1e-9 * discord.iter().sum::<f64>() + 1e-12 * linf * x.iter().map(|v| v * v).sum::<f64>()
}

#[test]
fn m1_parity_random_and_edge_cases() {
    let fx = fixture(); let cases = fx["cases"].as_array().unwrap(); assert!(cases.len() >= 60);
    let (ps, pe) = (H0Policy::m1_svd(M1_RANK_TOL), H0Policy::m1_eig(EIG_TOL));
    let (mut wd, mut wl, mut wdis, mut wp, mut we) = (0.0f64, 0.0f64, 0.0f64, 0.0f64, 0.0f64);
    for c in cases {
        let name = c["name"].as_str().unwrap();
        let dv: Vec<usize> = c["dv"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
        let raw: Vec<sheaf_cli::m1::RawM1Edge> = c["edges"].as_array().unwrap().iter().map(|e|
            (e["u"].as_u64().unwrap() as usize, e["v"].as_u64().unwrap() as usize, e["de"].as_u64().unwrap() as usize, f64s(&e["fu"]), f64s(&e["fv"]))).collect();
        let edges: Vec<cell::M1Edge> = raw.iter().map(|(u, v, de, fu, fv)| cell::M1Edge { u: *u, v: *v, de: *de, fu, fv }).collect();
        cell::check_edges(&dv, &edges).unwrap();
        let x = f64s(&c["x"]);
        // δ⁰
        let d = cell::coboundary(&dv, &edges);
        assert_eq!(d.idx.len() as u64, c["nnz_delta"].as_u64().unwrap(), "{name}: stored entries of δ (scipy sum_duplicates keeps explicit zeros)");
        let e = maxdiff(&dense(&d), &mat(&c["delta"])); assert!(e <= 1e-12, "{name} δ {e}"); wd = wd.max(e);
        // L₀
        let l = cell::drop_zeros(cell::laplacian(&d)); let lp = mat(&c["L"]);
        assert_eq!(l.idx.len() as u64, c["nnz_L"].as_u64().unwrap(), "{name}: stored entries of L");
        let e = maxdiff(&dense(&l), &lp); assert!(e <= 1e-12 * amax(&lp).max(1.0), "{name} L {e}"); wl = wl.max(e / amax(&lp).max(1.0));
        // discord, energy
        let de: Vec<usize> = edges.iter().map(|e| e.de).collect();
        let dis = cell::edge_discord(&d, &x, &de); wdis = wdis.max(check_discord(name, &dis, &f64s(&c["discord"])));
        let dense_d = dense(&d).concat();
        let dis2 = cell::edge_discord_dense(&dense_d, d.nrows, d.ncols, &x, &de); check_discord(name, &dis2, &f64s(&c["discord"]));
        let en = cell::energy(&l, &x); let ew = c["energy"].as_f64().unwrap();
        assert!((en - ew).abs() <= energy_tol(&dis, &l, &x), "{name} energy {en} vs {ew}"); we = we.max((en - ew).abs());
        assert!((cell::energy_dense(&dense(&l).concat(), l.nrows, &x) - ew).abs() <= energy_tol(&dis, &l, &x), "{name} dense energy");
        // H⁰, both routes
        let g = co::global_sections(&d, ps).unwrap();
        assert_eq!(g.ncols() as u64, c["h0_svd"].as_u64().unwrap(), "{name} h0 svd");
        assert_eq!(co::h0_dim_from_l(&l, pe).unwrap() as u64, c["h0_eig"].as_u64().unwrap(), "{name} h0 eig");
        let n = d.ncols; let proj: Vec<Vec<f64>> = (0..n).map(|i| (0..n).map(|j| (0..g.ncols()).map(|k| g[(i, k)] * g[(j, k)]).sum()).collect()).collect();
        if n > 0 { let e = maxdiff(&proj, &mat(&c["proj"])); assert!(e <= 1e-8, "{name} projector {e}"); wp = wp.max(e); }
        for a in 0..g.ncols() { for b in 0..g.ncols() {
            let s: f64 = (0..n).map(|i| g[(i, a)] * g[(i, b)]).sum(); assert!((s - if a == b { 1.0 } else { 0.0 }).abs() <= 1e-8, "{name} GᵀG");
        } }
        let smax = sheaf_cohom::m1::components(&d).iter().filter_map(|c| co::block_singular_values(&d, c).unwrap().first().copied()).fold(0.0, f64::max);
        let mut dg2 = 0.0; for k in 0..g.ncols() { let col: Vec<f64> = (0..n).map(|i| g[(i, k)]).collect(); dg2 += d.mul(&col).iter().map(|v| v * v).sum::<f64>(); }
        assert!(dg2.sqrt() <= 1e-6 * smax.max(1.0), "{name} ‖δG‖");
    }
    println!("M1-PARITY cases={} max|δ|={wd:e} max rel|L|={wl:e} max rel discord={wdis:e} max|E|={we:e} max|P|={wp:e}", cases.len());
}

#[test]
fn m1_parity_spec_fixture() {
    let fx = fixture(); let sp = &fx["spec"];
    let s: SheafSpec = serde_json::from_str(&std::fs::read_to_string(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/m1/spec.json")).unwrap()).unwrap();
    let m = sheaf_cli::m1::analyze(&s).unwrap();
    let shape: Vec<usize> = sp["shape"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as usize).collect();
    assert_eq!((m.delta.nrows, m.delta.ncols), (shape[0], shape[1]));
    let mut want = vec![vec![0.0; shape[1]]; shape[0]];
    for ((r, c), v) in sp["rows"].as_array().unwrap().iter().zip(sp["cols"].as_array().unwrap()).zip(sp["vals"].as_array().unwrap()) {
        want[r.as_u64().unwrap() as usize][c.as_u64().unwrap() as usize] += v.as_f64().unwrap();
    }
    assert_eq!(m.delta.idx.len() as u64, sp["nnz_delta"].as_u64().unwrap());
    let e = maxdiff(&dense(&m.delta), &want); assert!(e <= 1e-12, "spec δ {e}");
    assert_eq!(m.laplacian.idx.len() as u64, sp["nnz_L"].as_u64().unwrap());
    let wd = check_discord("spec", &m.discord, &f64s(&sp["discord"]));
    let x: Vec<f64> = s.x.iter().flatten().copied().collect();
    assert!((m.energy - sp["energy"].as_f64().unwrap()).abs() <= energy_tol(&m.discord, &m.laplacian, &x));
    assert_eq!(m.h0_svd as u64, sp["h0_svd"].as_u64().unwrap()); assert_eq!(m.h0_eig as u64, sp["h0_eig"].as_u64().unwrap());
    // and the gated crate's own discord agrees (R-RUST-20 bound ABS 1e-9)
    for (a, b) in m.discord.iter().zip(s.discord()) { assert!((a - b).abs() <= 1e-9 * b.abs().max(1.0)); }
    println!("M1-PARITY spec max rel discord={wd:e} h0_svd={} h0_eig={} policy: {} | {}", m.h0_svd, m.h0_eig, m.policy_svd, m.policy_eig);
}

fn apply(v: &mut Value, op: &Value) {   // same JSON-pointer ops as the gated r_model_mutation_table
    let path = op["path"].as_str().unwrap(); let (parent, key) = path.rsplit_once('/').unwrap();
    let tgt = if parent.is_empty() { &mut *v } else { v.pointer_mut(parent).unwrap() };
    match op["op"].as_str().unwrap() {
        "set" => match tgt { Value::Object(m) => { m.insert(key.to_string(), op["value"].clone()); }, Value::Array(a) => { a[key.parse::<usize>().unwrap()] = op["value"].clone(); }, _ => panic!() },
        "remove" => match tgt { Value::Object(m) => { m.remove(key); }, Value::Array(a) => { a.remove(key.parse::<usize>().unwrap()); }, _ => panic!() },
        "append" => { v.pointer_mut(path).unwrap().as_array_mut().unwrap().push(op["value"].clone()); },
        o => panic!("unknown op {o}"),
    }
}

/// Every row of the regenerated shared mutation table through the m1 adapter: `analyze` rejects exactly what the gated
/// `validate()` rejects (same req ID, incl. R-NONID-04 on every edge type), and on every accepted row the Rust math
/// matches the Python reference (discord, energy, H⁰ both routes, stored-entry counts).
#[test]
fn m1_parity_mutation_table() {
    let fx = fixture(); let table = fx["table"].as_array().unwrap();
    let base: Value = serde_json::from_str(&std::fs::read_to_string(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/m1/spec.json")).unwrap()).unwrap();
    let rows: Vec<Value> = serde_json::from_str(&std::fs::read_to_string(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/m1/mutations.json")).unwrap()).unwrap();
    assert_eq!(rows.len(), 114); assert_eq!(table.len(), rows.len());
    let (mut mismatches, mut compared, mut nonid) = (Vec::new(), 0, 0);
    for (case, py) in rows.iter().zip(table) {
        let name = case["name"].as_str().unwrap(); assert_eq!(py["name"].as_str().unwrap(), name);
        let mut v = base.clone(); for op in case["ops"].as_array().unwrap() { apply(&mut v, op); }
        let want = case["rust"].as_str().unwrap();
        let got = match serde_json::from_value::<SheafSpec>(v) { Err(_) => "serde".to_string(), Ok(s) => match sheaf_cli::m1::analyze(&s) {
            Err(e) => e, Ok(m) => {
                if py["models"] == "ok" {
                    compared += 1;
                    let x: Vec<f64> = s.x.iter().flatten().copied().collect();
                    check_discord(name, &m.discord, &f64s(&py["discord"]));
                    assert!((m.energy - py["energy"].as_f64().unwrap()).abs() <= energy_tol(&m.discord, &m.laplacian, &x), "{name} energy");
                    assert_eq!((m.h0_svd as u64, m.h0_eig as u64), (py["h0_svd"].as_u64().unwrap(), py["h0_eig"].as_u64().unwrap()), "{name} h0");
                    assert_eq!((m.delta.idx.len() as u64, m.laplacian.idx.len() as u64), (py["nnz_delta"].as_u64().unwrap(), py["nnz_L"].as_u64().unwrap()), "{name} nnz");
                }
                "ok".to_string()
            } } };
        if want == "R-NONID-04" { nonid += 1; }
        if got != want { mismatches.push(format!("{name}: {got} != {want}")); }
    }
    assert!(mismatches.is_empty(), "{mismatches:?}");
    assert!(compared >= 20 && nonid >= 5);
    println!("M1-PARITY table rows={} mismatches=0 accepted rows compared with Python={compared} R-NONID-04 rows rejected={nonid}", rows.len());
}

/// R-NONID-04 on the m1 path (ADR-016): an identity/identity pair is rejected before any math; one identity side is fine.
#[test]
fn m1_path_follows_r_nonid_04() {
    let mut s: SheafSpec = serde_json::from_str(&std::fs::read_to_string(std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../fixtures/m1/spec.json")).unwrap()).unwrap();
    let d = s.d; let id: Vec<Vec<f64>> = (0..d).map(|i| (0..d).map(|j| if i == j { 1.0 } else { 0.0 }).collect()).collect();
    let ty = *s.maps.keys().next().unwrap();
    let keep = s.maps[&ty].1.clone();
    s.maps.insert(ty, (id.clone(), keep));
    assert!(sheaf_cli::m1::analyze(&s).is_ok(), "one identity side is valid");
    s.maps.insert(ty, (id.clone(), id));
    assert_eq!(sheaf_cli::m1::analyze(&s).err().as_deref(), Some("R-NONID-04"));
}

/// The FFI's policy guard: the m1 H⁰ entry points refuse the non-m1 policies (no silent per-component cut).
#[test]
fn m1_h0_requires_contract_policy() {
    let d = Csr { nrows: 1, ncols: 2, ptr: vec![0, 2], idx: vec![0, 1], val: vec![-1.0, 1.0] };
    assert!(co::global_sections(&d, H0Policy::adr012()).is_err());
    assert!(co::h0_dim_from_l(&cell::laplacian(&d), H0Policy::m1_svd(1e-9)).is_err());
    assert_eq!(co::global_sections(&d, H0Policy::m1_svd(1e-9)).unwrap().ncols(), 1);
    assert_eq!(co::h0_dim_from_l(&cell::laplacian(&d), H0Policy::m1_eig(1e-10)).unwrap(), 1);
    // Grok R1 critical (fixed): a wide block's zero-padded singular values count when tol < 0, as in the reference
    // (sheafcore.global_sections([[1, 1]], tol=-1).shape == (2, 0))
    let w = Csr { nrows: 1, ncols: 2, ptr: vec![0, 2], idx: vec![0, 1], val: vec![1.0, 1.0] };
    assert_eq!(co::global_sections(&w, H0Policy::m1_svd(-1.0)).unwrap().ncols(), 0);
    assert_eq!(co::block_singular_values(&w, &co::components(&w)[0]).unwrap().len(), 2);
}

/// Grok R1 (refuted major, pinned): products that cancel are not stored, as in scipy's SpGEMM (nnz 2, not 4).
#[test]
fn m1_laplacian_cancellation_pattern() {
    let (fa, fb, fc) = ([1.0], [1.0], [-1.0]);
    let e = [cell::M1Edge { u: 0, v: 1, de: 1, fu: &fa, fv: &fb }, cell::M1Edge { u: 0, v: 1, de: 1, fu: &fa, fv: &fc }];
    let l = cell::drop_zeros(cell::laplacian(&cell::coboundary(&[1, 1], &e)));
    assert_eq!((l.idx.clone(), l.val.clone()), (vec![0, 1], vec![2.0, 2.0]));
}
